package com.ldtteam.structurize.client.rendertask;

import com.ldtteam.structurize.client.rendercontext.WorldEventRenderContext;
import com.ldtteam.structurize.client.rendertask.task.IRenderTask;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.annotation.Nullable;

public class RenderTaskManager {
    private static final Map<String, Map<String, IRenderTask>> RENDER_TASKS = new LinkedHashMap<String, Map<String, IRenderTask>>();

    public static void render(WorldEventRenderContext context) {
        if (RENDER_TASKS.isEmpty()) {
            return;
        }
        for (Map<String, IRenderTask> group : RENDER_TASKS.values()) {
            for (IRenderTask renderTask : group.values()) {
                if (!renderTask.shouldRenderIn(context.stageEvent.getStage())) continue;
                renderTask.render(context);
            }
        }
    }

    public static void onClientTick() {
        Iterator<Map<String, IRenderTask>> groups = RENDER_TASKS.values().iterator();
        while (groups.hasNext()) {
            Map<String, IRenderTask> group = groups.next();
            Iterator<IRenderTask> containers = group.values().iterator();
            while (containers.hasNext()) {
                IRenderTask renderDataContainer = containers.next();
                boolean isDone = renderDataContainer.tick();
                if (!isDone) continue;
                containers.remove();
            }
            if (!group.isEmpty()) continue;
            groups.remove();
        }
    }

    public static void clearHighlightsForKey(String key) {
        RENDER_TASKS.remove(key);
    }

    public static IRenderTask addRenderTask(String key, IRenderTask task) {
        return RENDER_TASKS.computeIfAbsent(key, k -> new LinkedHashMap()).put(task.id(), task);
    }

