@Mod.EventBusSubscriber(modid="sword_soaring", value={Dist.CLIENT})
public class ClientInputManager {
    public static long lastPressTime;

    @SubscribeEvent
    public static void onClientTick(TickEvent.ClientTickEvent event) {
        if (event.phase == TickEvent.Phase.START) {
            return;
        }
        while (SwordSoaringKeyMappings.TAKE_OFF.m_90859_()) {
            LocalPlayer localPlayer = Minecraft.m_91087_().f_91074_;
            long currentTime = System.currentTimeMillis();
            if (localPlayer != null && !localPlayer.m_20096_() && currentTime - lastPressTime < (long)((Integer)SwordSoaringConfig.FLY_DELAY.get()).intValue()) {
                ClientInputManager.sendSkillPacket(SwordSoaringSkillSlots.SWORD_SOARING, SwordSoaringKeyMappings.TAKE_OFF);
            }
            lastPressTime = System.currentTimeMillis();
        }
        while (SwordSoaringKeyMappings.SWORD_SKILL.m_90859_()) {
            ClientInputManager.sendSkillPacket(SwordSoaringSkillSlots.SWORD_CONTROLLER, SwordSoaringKeyMappings.SWORD_SKILL);
        }
        while (SwordSoaringKeyMappings.SWITCH_MODE.m_90859_()) {
            ClientInputManager.switchModeKeyPressed();
        }
        while (SwordSoaringKeyMappings.SWORD_BACK.m_90859_()) {
            ClientInputManager.swordBackKeyPressed();
        }
    }

    public static void swordBackKeyPressed() {
        PacketRelay.sendToServer(PacketHandler.INSTANCE, new RequestVatanseverSwordBackPacket());
    }

    public static void switchModeKeyPressed() {
        LocalPlayerPatch localPlayerPatch = (LocalPlayerPatch)EpicFightCapabilities.getEntityPatch((Entity)Minecraft.m_91087_().f_91074_, LocalPlayerPatch.class);
        if (localPlayerPatch != null) {
            SkillContainer skillContainer = localPlayerPatch.getSkill((SkillSlot)SwordSoaringSkillSlots.SWORD_SOARING);
            List<Skill> learnedSkills = localPlayerPatch.getSkillCapability().listAcquiredSkills().filter(skill -> skill.getCategory() == SwordSoaringSkillCategories.SWORD_SOARING).toList();
            if (learnedSkills.isEmpty()) {
                return;
            }
            int index = learnedSkills.indexOf(skillContainer.getSkill());
            int next = (index + 1) % learnedSkills.size();
            Skill nextSkill = learnedSkills.get(next);
            skillContainer.setSkill(nextSkill);
            EpicFightNetworkManager.sendToServer((Object)new CPChangeSkill((SkillSlot)SwordSoaringSkillSlots.SWORD_SOARING, -1, nextSkill));

